import numpy as np

def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    n_unvisited = len(unvisited_nodes)
    if n_unvisited == 0:
        return destination_node
    # Compute scores: squared distance from current + (distance to destination) / remaining nodes
    scores = distance_matrix[current_node][unvisited_nodes] ** 2 + distance_matrix[unvisited_nodes][:, destination_node] / n_unvisited
    best_idx = np.argmin(scores)
    return int(unvisited_nodes[best_idx])

